"""Structural validation for XML generated by tests/generate-xml.mjs.

This checks XML well-formedness and the exact project structure we intend to
emit. It is not an Alight Motion schema validator; that requires importing the
file into the app.
"""

import sys
import xml.etree.ElementTree as ET
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8", errors="replace")


def check(condition, message):
    if not condition:
        raise AssertionError(message)


def load(path):
    raw = Path(path).read_bytes()
    check(not raw.startswith(b"\xef\xbb\xbf"), f"{path}: unexpected BOM")
    check(
        raw.startswith(b"<?xml version='1.0' encoding='UTF-8' ?>"),
        f"{path}: unexpected XML declaration",
    )
    text = raw.decode("utf-8")
    root = ET.fromstring(raw)
    check(root.tag == "scene", f"{path}: root is {root.tag}")
    texts = root.findall("text")
    ids = []
    for node in texts:
        check(node.get("id", "").isdigit(), f"{path}: non-numeric id {node.get('id')!r}")
        ids.append(int(node.get("id")))
        check(node.get("startTime", "").isdigit(), f"{path}: bad startTime")
        check(node.get("endTime", "").isdigit(), f"{path}: bad endTime")
        for bad_child in ("kf", "effect", "media", "audio", "bookmark"):
            check(
                node.find(bad_child) is None,
                f"{path}: unexpected <{bad_child}> below <text>",
            )
    check(len(ids) == len(set(ids)), f"{path}: duplicate ids")
    for bad_child in ("kf", "effect", "media", "audio", "bookmark", "shape"):
        check(root.find(bad_child) is None, f"{path}: unexpected <{bad_child}> in scene")
    return raw, text, root, texts


def main(paths):
    check(len(paths) >= 4, "expected four XML files")
    loaded = {Path(p).name: load(p) for p in paths}

    raw, text, root, texts = loaded["landscape-srt.xml"]
    check(root.get("width") == "1920", "landscape width")
    check(root.get("height") == "1080", "landscape height")
    check(root.get("totalTime") == "15000", "landscape totalTime")
    check(len(texts) == 6, f"landscape text count {len(texts)}")
    check(texts[0].get("startTime") == "1000", "landscape first start")
    check(texts[0].get("endTime") == "3500", "landscape first end")
    check(texts[-1].get("startTime") == "13000", "landscape last start")
    check(texts[-1].get("endTime") == "14000", "landscape last end")
    check(texts[0].find("content").text == "第一行\n第二行 & 结尾", "landscape content 1")
    check(texts[1].find("content").text == "重叠字幕 测试", "landscape content 2")
    check(texts[2].find("content").text == "无序号 <tag> 与 ASS", "landscape content 3")
    check(texts[3].find("content").text == "换行\n测试", "landscape content 4")
    check(
        texts[0].find("transform/location").get("value")
        == "960.000000,918.000000,0.000000",
        "landscape location",
    )
    check(texts[0].get("wrapWidth") == "1728", "landscape wrapWidth")
    check(texts[0].get("font") == "googlefonts?name=Roboto&weight=900", "landscape font")
    check(texts[0].find("fillColor").get("value") == "#ffffffff", "landscape fillColor")
    check('font="googlefonts?name=Roboto&amp;weight=900"' in text, "landscape font escaping")
    check("<content>第一行\n第二行 &amp; 结尾</content>" in text, "landscape content escaping")
    check('modifiedTime="1700000000000"' in text, "landscape modifiedTime")

    raw, text, root, texts = loaded["portrait-lrc.xml"]
    check(root.get("width") == "1080", "portrait width")
    check(root.get("height") == "1920", "portrait height")
    check(root.get("totalTime") == "16500", "portrait totalTime")
    check(len(texts) == 6, f"portrait text count {len(texts)}")
    check(texts[0].get("startTime") == "500", "portrait first start")
    check(texts[0].get("endTime") == "2500", "portrait first end")
    check(texts[3].find("content").text == "原文\nTranslation", "portrait merged content")
    check(texts[4].find("content").text == "逐字歌词", "portrait word-tag content")
    check(texts[-1].get("startTime") == "12500", "portrait last start")
    check(texts[-1].get("endTime") == "15500", "portrait last end")
    check(
        texts[0].find("transform/location").get("value")
        == "540.000000,1632.000000,0.000000",
        "portrait location",
    )
    check(texts[0].get("wrapWidth") == "972", "portrait wrapWidth")
    check("<content>原文\nTranslation</content>" in text, "portrait newline indentation")
    check('modifiedTime="1700000000000"' in text, "portrait modifiedTime")

    raw, text, root, texts = loaded["perchar-karaoke.xml"]
    check(root.get("width") == "1080", "perchar width")
    check(root.get("height") == "1920", "perchar height")
    check(root.get("totalTime") == "7500", "perchar totalTime")
    check(len(texts) == 10, f"perchar text count {len(texts)}")
    expected = [
        ("1000", "1500", "私"),
        ("1500", "2000", "私の"),
        ("2000", "2500", "私の居"),
        ("2500", "3000", "私の居ぬ"),
        ("3000", "3500", "私の居ぬ将"),
        ("3500", "4000", "私の居ぬ将来"),
        ("4000", "4500", "私の居ぬ将来に"),
        ("5000", "5500", "次"),
        ("5500", "6000", "次の"),
        ("6000", "6500", "次の行"),
    ]
    for node, (start, end, content) in zip(texts, expected):
        check(node.get("startTime") == start, f"perchar start {start}: {node.get('startTime')}")
        check(node.get("endTime") == end, f"perchar end {end}: {node.get('endTime')}")
        check(node.find("content").text == content, f"perchar content {content!r}")
    check(
        texts[0].find("transform/location").get("value")
        == "540.000000,1632.000000,0.000000",
        "perchar location",
    )
    check(texts[0].get("wrapWidth") == "972", "perchar wrapWidth")

    raw, text, root, texts = loaded["perchar-chars.xml"]
    check(root.get("width") == "1080", "perchar chars width")
    check(root.get("height") == "1920", "perchar chars height")
    check(root.get("totalTime") == "7500", "perchar chars totalTime")
    check(len(texts) == 10, f"perchar chars text count {len(texts)}")
    expected_chars = [
        ("1000", "4500", "私", "288.000000"),
        ("1500", "4500", "の", "372.000000"),
        ("2000", "4500", "居", "456.000000"),
        ("2500", "4500", "ぬ", "540.000000"),
        ("3000", "4500", "将", "624.000000"),
        ("3500", "4500", "来", "708.000000"),
        ("4000", "4500", "に", "792.000000"),
        ("5000", "6500", "次", "456.000000"),
        ("5500", "6500", "の", "540.000000"),
        ("6000", "6500", "行", "624.000000"),
    ]
    for node, (start, end, content, x) in zip(texts, expected_chars):
        check(node.get("startTime") == start, f"perchar chars start {start}: {node.get('startTime')}")
        check(node.get("endTime") == end, f"perchar chars end {end}: {node.get('endTime')}")
        check(node.find("content").text == content, f"perchar chars content {content!r}")
        check(
            node.find("transform/location").get("value") == f"{x},1632.000000,0.000000",
            f"perchar chars location x={x}: {node.find('transform/location').get('value')}",
        )
        check(
            node.find("transform/scale").get("value") == "1.000000,1.000000",
            "perchar chars scale",
        )
    check(texts[0].get("wrapWidth") == "972", "perchar chars wrapWidth")

    print("OK: " + ", ".join(Path(p).name for p in paths))


if __name__ == "__main__":
    try:
        main(sys.argv[1:])
    except AssertionError as exc:
        print("FAIL: " + str(exc))
        sys.exit(1)
